create table public.sample_profiles(id text primary key check(id like 'sample-%'),name text not null,gender text not null check(gender in ('Male','Female')),age integer not null check(age between 21 and 80),city text not null,education text not null,occupation text not null,height_cm integer not null,religion text not null,mother_tongue text not null,star text not null,about text not null,published boolean not null default true);
alter table public.sample_profiles enable row level security;
create policy published_samples on public.sample_profiles for select to anon,authenticated using(published);
create policy admin_samples on public.sample_profiles for all to authenticated using(private.admin_verified()) with check(private.admin_verified());
grant select on public.sample_profiles to anon,authenticated;
grant all on public.sample_profiles to service_role;
